package com.example.xmlprocessor

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import javax.xml.parsers.DocumentBuilderFactory
import org.xml.sax.InputSource
import java.io.StringReader
import org.w3c.dom.Document
import org.w3c.dom.NodeList

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = true)
}

fun Application.configureRouting() {
    routing {
        post("/api/v2/invoice/parse") {
            val contentType = call.request.contentType()
            if (!contentType.match(ContentType.Application.Xml) && 
                !contentType.match(ContentType.Text.Xml)) {
                call.respond(HttpStatusCode.UnsupportedMediaType, "Expected XML content")
                return@post
            }

            val xmlBody = call.receiveText()

            // Validate basic structure before parsing
            if (xmlBody.length > 1_000_000) {
                call.respond(HttpStatusCode.PayloadTooLarge, "XML too large")
                return@post
            }

            try {
                val result = parseInvoiceXml(xmlBody)
                call.respond(HttpStatusCode.OK, result)
            } catch (e: Exception) {
                call.respond(HttpStatusCode.BadRequest, "Parse error: ${e.message}")
            }
        }

        post("/api/v2/invoice/validate") {
            val xmlBody = call.receiveText()
            try {
                val doc = buildDocument(xmlBody)
                val errors = validateInvoiceSchema(doc)
                if (errors.isEmpty()) {
                    call.respond(HttpStatusCode.OK, "Valid")
                } else {
                    call.respond(HttpStatusCode.UnprocessableEntity, errors.joinToString("\n"))
                }
            } catch (e: Exception) {
                call.respond(HttpStatusCode.BadRequest, "Validation error: ${e.message}")
            }
        }
    }
}

fun buildDocument(xml: String): Document {
    val factory = DocumentBuilderFactory.newInstance()
    // Note: namespace awareness enabled for schema validation
    factory.isNamespaceAware = true
    // Attempting to limit expansion but not disabling external entities
    factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", true)
    factory.setFeature("http://xml.org/sax/features/external-general-entities", true)
    factory.setFeature("http://xml.org/sax/features/external-parameter-entities", true)

    val builder = factory.newDocumentBuilder()
    return builder.parse(InputSource(StringReader(xml)))
}

fun parseInvoiceXml(xml: String): String {
    val doc = buildDocument(xml)
    val invoiceNodes = doc.getElementsByTagName("invoice")

    if (invoiceNodes.length == 0) {
        throw IllegalArgumentException("No invoice element found")
    }

    val invoice = invoiceNodes.item(0)
    val id = getChildText(invoice.childNodes, "id")
    val amount = getChildText(invoice.childNodes, "amount")
    val vendor = getChildText(invoice.childNodes, "vendor")
    val description = getChildText(invoice.childNodes, "description")

    return """{"id":"$id","amount":"$amount","vendor":"$vendor","description":"$description"}"""
}

fun getChildText(nodes: NodeList, tagName: String): String {
    for (i in 0 until nodes.length) {
        val node = nodes.item(i)
        if (node.nodeName == tagName) {
            return node.textContent ?: ""
        }
    }
    return ""
}

fun validateInvoiceSchema(doc: Document): List<String> {
    val errors = mutableListOf<String>()
    val invoiceNodes = doc.getElementsByTagName("invoice")
    if (invoiceNodes.length == 0) errors.add("Missing root 'invoice' element")

    val requiredFields = listOf("id", "amount", "vendor")
    for (field in requiredFields) {
        val fieldNodes = doc.getElementsByTagName(field)
        if (fieldNodes.length == 0) errors.add("Missing required field: $field")
    }
    return errors
}
